def maximumOr(nums, k):
    n = len(nums)
    pre = [0] * (n + 1)
    suf = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] | nums[i]
    for i in range(n - 1, -1, -1):
        suf[i] = suf[i + 1] | nums[i]
    return max(pre[i] | (nums[i] << k) | suf[i + 1] for i in range(n))

