def count(num1, num2, min_sum, max_sum):
    MOD = 10 ** 9 + 7
    def f(num):
        digits = [int(ch) for ch in num]
        n = len(digits)
        memo = {}
        def go(i, s, tight):
            if s > max_sum:
                return 0
            if i == n:
                return 1 if s >= min_sum else 0
            key = (i, s, tight)
            if key in memo:
                return memo[key]
            hi = digits[i] if tight else 9
            res = 0
            for d in range(hi + 1):
                res += go(i + 1, s + d, tight and d == hi)
            res %= MOD
            memo[key] = res
            return res
        return go(0, 0, True)
    return (f(num2) - f(str(int(num1) - 1))) % MOD

