def colorTheArray(n, queries):
    nums = [0] * n
    cnt = 0
    out = []
    for idx, c in queries:
        old = nums[idx]
        if old != 0:
            if idx > 0 and nums[idx - 1] == old:
                cnt -= 1
            if idx < n - 1 and nums[idx + 1] == old:
                cnt -= 1
        nums[idx] = c
        if idx > 0 and nums[idx - 1] == c:
            cnt += 1
        if idx < n - 1 and nums[idx + 1] == c:
            cnt += 1
        out.append(cnt)
    return out

