def sumOfPower(nums):
    MOD = 10 ** 9 + 7
    nums = sorted(nums)
    ans = 0
    s = 0
    for i, v in enumerate(nums):
        if i > 0:
            s = (2 * s + nums[i - 1]) % MOD
        ans = (ans + v * v % MOD * ((v + s) % MOD)) % MOD
    return ans

