def longestSemiRepetitiveSubstring(s):
    n = len(s)
    left = 0
    pairs = 0
    best = 1
    for right in range(1, n):
        if s[right] == s[right - 1]:
            pairs += 1
        while pairs > 1:
            left += 1
            if s[left] == s[left - 1]:
                pairs -= 1
        if right - left + 1 > best:
            best = right - left + 1
    return best

