def punishmentNumber(n):
    def can(target, s, idx, cur):
        if idx == len(s):
            return cur == target
        v = 0
        for j in range(idx, len(s)):
            v = v * 10 + int(s[j])
            if cur + v > target:
                break
            if can(target, s, j + 1, cur + v):
                return True
        return False
    return sum(i * i for i in range(1, n + 1) if can(i, str(i * i), 0, 0))

