def paintWalls(cost, time):
    n = len(cost)
    INF = float('inf')
    dp = [INF] * (n + 1)
    dp[0] = 0
    for c, t in zip(cost, time):
        for j in range(n, 0, -1):
            k = j - t - 1
            if k < 0:
                k = 0
            if dp[k] + c < dp[j]:
                dp[j] = dp[k] + c
    return dp[n]

