def minCost(nums, x):
    n = len(nums)
    best = list(nums)
    ans = sum(best)
    for k in range(1, n):
        for i in range(n):
            v = nums[(i + k) % n]
            if v < best[i]:
                best[i] = v
        cur = sum(best) + k * x
        if cur < ans:
            ans = cur
    return ans
